from pathlib import Path

p = Path('src/services/ege_exam_service.py')
text = p.read_text(encoding='utf-8')
anchor = '''def verify_tutor_pilot_answer(task_number: int, answer: str) -> bool:\n    expected = str(TUTOR_PILOT_TASKS[task_number]["answer"]).strip().lower()\n    return answer.strip().lower() == expected\n\n\n'''
insert = '''TUTOR_PILOT_TRANSFER_TASKS = {\n    5: {\n        "statement": (\n            "Для натурального числа N строят его двоичную запись. Если запись оканчивается на 1, "\n            "справа дописывают 0, иначе справа дописывают 11. Полученную двоичную запись рассматривают "\n            "как число R. Найдите наибольшее N от 12 до 24 включительно, для которого R < 50."\n        ),\n        "answer": "23",\n    },\n    14: {\n        "statement": (\n            "Число 686 перевели из десятичной системы в шестнадцатеричную. "\n            "Сколько цифр полученной записи имеют чётное числовое значение?"\n        ),\n        "answer": "3",\n    },\n    27: {\n        "statement": (\n            "Даны два кластера точек: A={(1,1),(1,3),(1,5)} и "\n            "B={(20,20),(22,20),(24,20)}. Медоидом кластера считается точка с минимальной "\n            "суммой расстояний до остальных точек своего кластера. Найдите сумму всех координат двух медоидов."\n        ),\n        "answer": "46",\n    },\n}\n\n\ndef render_tutor_pilot_transfer_task(task_number: int) -> str:\n    task = TUTOR_PILOT_TRANSFER_TASKS[task_number]\n    return (\n        "━━━━━━━━━━━━━━━━━━━━\\n"\n        f"🎯 БЕЗ ПОДСКАЗКИ · КЕГЭ №{task_number}\\n"\n        "━━━━━━━━━━━━━━━━━━━━\\n\\n"\n        "Теперь похожая задача без разбора и примера.\\n\\n"\n        f"{task['statement']}\\n\\n"\n        "Отправь только итоговый ответ."\n    )\n\n\ndef verify_tutor_pilot_transfer_answer(task_number: int, answer: str) -> bool:\n    expected = str(TUTOR_PILOT_TRANSFER_TASKS[task_number]["answer"]).strip().lower()\n    return answer.strip().lower() == expected\n\n\ndef record_tutor_pilot_transfer_answer(attempt: ExamAttempt, task_number: int, answer: str) -> bool:\n    """Verify independent transfer; open diagnostics only when support did not transfer."""\n    is_correct = verify_tutor_pilot_transfer_answer(task_number, answer)\n    if not is_correct:\n        attempt.answers[task_number] = answer\n        attempt.results[task_number] = False\n        attempt.diagnostics[task_number] = open_diagnostic_case(\n            task_number=task_number,\n            student_answer=answer,\n            expected_answer=str(TUTOR_PILOT_TRANSFER_TASKS[task_number]["answer"]),\n            skill_map=load_skill_map(),\n        )\n    return is_correct\n\n\n'''
if anchor not in text:
    raise SystemExit('verify tutor anchor missing')
text = text.replace(anchor, anchor + insert, 1)
p.write_text(text, encoding='utf-8')

p = Path('src/telegram_bot/handlers/student.py')
text = p.read_text(encoding='utf-8')
old = '''    await state.update_data(ege_attempt=attempt.to_dict(), tutor_pilot_index=0)\n'''
new = '''    await state.update_data(ege_attempt=attempt.to_dict(), tutor_pilot_index=0, tutor_pilot_stage="supported")\n'''
if old not in text:
    raise SystemExit('start state anchor missing')
text = text.replace(old, new, 1)
start = text.index('async def receive_ege_tutor_pilot_answer')
end = text.index('\n\nasync def start_ege_diagnostic_pilot', start)
replacement = '''async def receive_ege_tutor_pilot_answer(message: Message, state: FSMContext) -> None:\n    from src.services.ege_exam_service import (\n        ExamAttempt,\n        record_tutor_pilot_answer,\n        record_tutor_pilot_transfer_answer,\n        render_tutor_pilot_task,\n        render_tutor_pilot_transfer_task,\n    )\n    data = await state.get_data()\n    attempt_data = data.get("ege_attempt")\n    if not attempt_data:\n        await state.clear()\n        await message.answer("Пилотная сессия не найдена. Запусти /test_ege_tutor.")\n        return\n    attempt = ExamAttempt.from_dict(attempt_data)\n    tasks = (5, 14, 27)\n    index = int(data.get("tutor_pilot_index", 0))\n    stage = str(data.get("tutor_pilot_stage", "supported"))\n    if not 0 <= index < len(tasks):\n        await state.clear()\n        await message.answer("Пилотная сессия завершена. Запусти /test_ege_tutor заново.")\n        return\n    task_number = tasks[index]\n\n    if stage == "supported":\n        is_correct = record_tutor_pilot_answer(attempt, task_number, message.text or "")\n        if is_correct:\n            await message.answer("✅ Верно. Теперь проверим тот же навык на новой задаче без примера и подсказок.")\n            await state.update_data(ege_attempt=attempt.to_dict(), tutor_pilot_stage="transfer")\n            save_ege_session(message.from_user.id, attempt.to_dict(), status="tutor_pilot_in_progress")\n            await message.answer(render_tutor_pilot_transfer_task(task_number))\n            return\n        await message.answer("❌ Ответ неверный. Зафиксирую ошибку и после трёх заданий разберём именно её.")\n    else:\n        is_correct = record_tutor_pilot_transfer_answer(attempt, task_number, message.text or "")\n        if is_correct:\n            await message.answer("✅ Получилось и без подсказки. Этот навык пока не требует диагностики.")\n        else:\n            await message.answer("❌ На новой задаче без подсказки возникла ошибка. После пилота разберём, на каком шаге она появилась.")\n\n    index += 1\n    await state.update_data(ege_attempt=attempt.to_dict(), tutor_pilot_index=index, tutor_pilot_stage="supported")\n    save_ege_session(message.from_user.id, attempt.to_dict(), status="tutor_pilot_in_progress")\n    if index < len(tasks):\n        await message.answer(render_tutor_pilot_task(tasks[index]))\n        return\n    if not attempt.diagnostics:\n        save_ege_session(message.from_user.id, attempt.to_dict(), status="completed")\n        await state.clear()\n        await message.answer(\n            "🏆 Все три навыка подтверждены на новых задачах без подсказок. "\n            "Диагностика не нужна. Следующий уровень — экзаменационные формулировки без учебного разбора."\n        )\n        return\n    await message.answer(\n        "Теперь разберём только те задания, где ошибка сохранилась или появилась после снятия подсказок. "\n        "Каждая проверка будет привязана к конкретному навыку."\n    )\n    await _begin_ege_diagnostics(message, state, attempt)\n'''
text = text[:start] + replacement + text[end:]
p.write_text(text, encoding='utf-8')

p = Path('tests/test_ege_tutor_pilot.py')
text = p.read_text(encoding='utf-8')
text = text.replace('    render_tutor_pilot_task,\n)', '    render_tutor_pilot_task,\n    render_tutor_pilot_transfer_task,\n    record_tutor_pilot_transfer_answer,\n)')
addition = '''\n\ndef test_supported_success_requires_independent_transfer_before_mastery_signal():\n    attempt = create_task_first_tutor_attempt()\n    assert record_tutor_pilot_answer(attempt, 5, TUTOR_PILOT_TASKS[5]["answer"]) is True\n    assert 5 not in attempt.diagnostics\n    assert record_tutor_pilot_transfer_answer(attempt, 5, "999") is False\n    assert 5 in attempt.diagnostics\n\n\ndef test_transfer_task_removes_teacher_scaffolding():\n    rendered = render_tutor_pilot_transfer_task(5)\n    assert "БЕЗ ПОДСКАЗКИ" in rendered\n    assert "Разобранный пример" not in rendered\n    assert "Что здесь нужно понять" not in rendered\n    assert "N = 13" not in rendered\n'''
if 'test_supported_success_requires_independent_transfer_before_mastery_signal' not in text:
    text += addition
p.write_text(text, encoding='utf-8')
